import{_ as a}from"./chunks/image4.-AF4PoMn.js";import{_ as t,o as i,c as s,ag as o}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/image2.png",r="/nada-documentation/images/image3.png",l="/nada-documentation/images/image5.png",c="/nada-documentation/images/image6.png",d="/nada-documentation/images/image7.png",p="/nada-documentation/images/image8.png",m="/nada-documentation/images/image9.png",h="/nada-documentation/images/image10.png",g="/nada-documentation/images/image11.png",u="/nada-documentation/images/image12.png",f="/nada-documentation/images/image13.png",b="/nada-documentation/images/image14.png",_="/nada-documentation/images/image15.png",D=JSON.parse('{"title":"User interface","description":"","frontmatter":{},"headers":[],"relativePath":"intro/overview-ui.md","filePath":"intro/overview-ui.md","lastUpdated":1786379412000}'),v={name:"intro/overview-ui.md"};function y(w,e,q,x,A,T){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="user-interface" tabindex="-1">User interface <a class="header-anchor" href="#user-interface" aria-label="Permalink to &quot;User interface&quot;">​</a></h1><p>A demo catalog is available at <a href="http://nada-demo.ihsn.org/index.php/home" target="_blank" rel="noreferrer">http://nada-demo.ihsn.org</a> which demonstrates the main features of the NADA application. The examples we provide here are extracted from this catalog. As the content may be subject to frequent changes, the examples below may not fully correspond to the on-line version.</p><p><img src="'+n+'" alt=""></p><p>The main page of NADA is a listing of all datasets available in the catalog. In the default view, all data types are listed in the same page. Tabs (and a facet) are provided allowing users to filter the listing by data type. Only tabs for which data are available in the catalog will be displayed. Few catalogs are expected to have tabs for all data types.</p><p><img src="'+r+'" alt=""></p><p>The left panel will provide a set of facets (filters), which can be specific to each data type. Facets provide a convenient solution for users to select data that meet their requirements based on a selection of categorical (not continuous) metadata elements. As some metadata elements may be specific to the data type (e.g., the element &quot;album&quot; is only used for documenting images, or the element &quot;Software/language&quot; is only applicable to scripts), different facets are displayed in the type-specific tabs.</p><p><img src="'+a+'" alt=""></p><p>When filters are applied, the selection(s) will be displayed in pills above the listing of results.</p><p><img src="'+l+'" alt=""></p><p>In addition to facets, users can identify datasets of interest using the <strong>search</strong> tool. Depending on the configuration of the catalog. In NADA 5.2, a lexical search is implemented (future versions will provide lexical and semantic searchability).</p><p><img src="'+c+'" alt=""></p><p>The results of search and filter(s) will be displayed for the whole catalog (&quot;All&quot; tab) and by data type.</p><p><img src="'+d+'" alt=""></p><p>For <strong>[microdata]{.underline}</strong>, the search engine will not only identify the [datasets]{.underline} where the keyword was found, but also the specific [variables]{.underline} that match the query.</p><p><img src="'+p+'" alt=""></p><p>For microdata, a &quot;Variable view&quot; option is provided to display a list of variables (instead of a list of studies) that match the keyword. Variables can be selected for comparison. The more metadata are provided in the catalog, the more useful these comparisons will be to users who want to assess the consistency of variables across sources. The metadata can (and should) contain elements like the formulation of the question and the interviewer instructions (for survey and census microdata), information on how the variable was calculated, universe of population covered by the variable, variable and value labels, and summary statistics as relevant.</p><p><img src="'+m+'" alt=""></p><p><img src="'+h+'" alt=""></p><p>For all entries in the catalog, all available metadata are displayed in the entry page.</p><p><img src="'+g+'" alt=""></p><p>Some entries may include visualizations, if provided by the data curator.</p><p><img src="'+u+'" alt=""></p><p>Some entries may also provide a data preview grid.</p><p><img src="'+f+'" alt=""></p><p>Some entries will provide direct, unrestricted access to the related resources (documents, images, datasets, scripts, etc.) Other entries may impose some restrictions. This will often be the case for microdata. Microdata may be published as open data, as public use files, as datasets accessible under license, as datasets available from external repositories, as data accessible in data enclaves, or as data not accessible (in which case only the metadata and resources like questionnaires, reports, tables, and others will be published). Depending on the access policy, users will be able to download the data, or to register and request access to datasets.</p><p><img src="'+b+'" alt=""></p><p>Users will have access to all metadata and to selected data via API.</p><p><a href="https://nada-demo.ihsn.org/index.php/api/tables" target="_blank" rel="noreferrer">https://nada-demo.ihsn.org/index.php/api/tables</a></p><p><img src="'+_+'" alt=""></p>',29)])])}const I=t(v,[["render",y]]);export{D as __pageData,I as default};
